function Sparkline({ tone = 'blue', data = [], value }: { tone?: string; data?: number[]; value?: number }) {
  const [history, setHistory] = useState(() => [value ?? data[data.length - 1] ?? 0])
  useEffect(() => {
    if (value === undefined || history[history.length - 1] === value) return
    setHistory(current => [...current, value].slice(-12))
  }, [value])
  const values = value === undefined ? (data.length ? data : [0]) : history
  const max = Math.max(...values, 1)
  const min = Math.min(...values)
  const points = values.map((value, i) => `${(i / Math.max(values.length - 1, 1)) * 220},${42 - ((value - min) / Math.max(max - min, 1)) * 32}`).join(' ')
  const area = `0,48 ${points} 220,48`
  return <svg className={`spark ${tone}`} viewBox="0 0 220 48" preserveAspectRatio="none" aria-hidden="true"><polygon points={area} fill="currentColor" opacity=".08"/><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2" vectorEffect="non-scaling-stroke"/></svg>
}

const pretty = value => String(value || '') === 'trufflehog' ? 'TruffleHog' : String(value || '').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
const relativeTime = value => { if (!value) return '—'; const minutes = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 60000)); return minutes < 1 ? 'just now' : minutes < 60 ? `${minutes}m ago` : minutes < 2880 ? `${Math.round(minutes / 60)}h ago` : `${Math.round(minutes / 1440)}d ago` }
const duration = (run: Execution) => run.startedAt && run.finishedAt ? `${Math.max(1, Math.round((new Date(run.finishedAt).getTime() - new Date(run.startedAt).getTime()) / 1000))}s` : '—'
// Alerts are operational/security signals needing action: blocked repositories, scanners whose latest run failed
// (a later success clears it), and open verified findings. Runs arrive newest first.
const buildAlerts = (runs: Execution[], findings: Finding[], repos: Repository[]) => {
  const seen = new Set<string>()
  const inventory = new Set(repos.map(r => r.id)) // findings/runs of repositories no longer managed are not actionable
  return [
    ...repos.filter(r => r.status === 'Blocked').map(r => ({ title: 'Repository blocked', detail: `${r.name}: a verified finding blocks scheduled scans until unblocked`, severity: 'High', key: `repo:${r.id}`, target: { kind: 'repo' as const, id: r.id } })),
    ...runs.filter(r => inventory.has(r.repositoryId)).filter(r => { const key = `${r.repositoryId}/${r.scanner}`; if (seen.has(key)) return false; seen.add(key); return r.status === 'failed' }).map(r => ({ title: `Failed ${pretty(r.scanner)} run`, detail: `${r.repositoryId}${r.failureReason ? ` · ${r.failureReason}` : ''}`, severity: 'High', key: `run:${r.id}`, time: r.finishedAt || r.createdAt, target: { kind: 'run' as const, id: r.id } })),
    ...findings.filter(f => f.state === 'open' && f.severity === 'critical' && inventory.has(f.repositoryId)).map(f => ({ title: `${f.detector} (verified)`, detail: `${f.repositoryId} · ${f.safePath}`, severity: 'Critical', key: `finding:${f.fingerprint}`, time: f.lastSeen, target: { kind: 'findings' as const, id: f.repositoryId } }))
  ]
}
const chartTime = (value: string) => { if (!value) return '—'; const date = new Date(value); return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) }
const bucketCounts = (items: any[], dateField: string, days: number, predicate?: (item: any) => boolean) => { const buckets = new Array(days).fill(0); const now = Date.now(); items.forEach(item => { if (predicate && !predicate(item)) return; const t = item[dateField] ? new Date(item[dateField]).getTime() : NaN; if (Number.isNaN(t)) return; const idx = days - 1 - Math.floor((now - t) / 86400000); if (idx >= 0 && idx < days) buckets[idx]++ }); return buckets }
const weekday = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
function describeCron(expr: string) {
  const parts = (expr || '').trim().split(/\s+/)
  if (parts.length !== 5) return null
  const [min, hour, dom, month, dow] = parts
  if (dom !== '*' || month !== '*') return null
  if (!/^\d+$/.test(min) || !/^\d+$/.test(hour)) return null
  const time = `${hour.padStart(2, '0')}:${min.padStart(2, '0')}`
  if (dow === '*') return `Runs every day at ${time}`
  if (/^\d+$/.test(dow)) return `Runs every ${weekday[Number(dow) % 7]} at ${time}`
  if (/^\d+(,\d+)*$/.test(dow)) return `Runs on ${dow.split(',').map(d => weekday[Number(d) % 7]).join(', ')} at ${time}`
  return null
}
const escapeHtml = (value: string) => value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
function TokenTextarea({ value, onChange, ariaLabel, disabled, placeholder }: { value: string; onChange: (e: any) => void; ariaLabel: string; disabled?: boolean; placeholder?: string }) {
  const preRef = useRef<HTMLPreElement>(null)
  const highlighted = escapeHtml(value || '').replace(/\{\{(\w+)\}\}/g, '<mark>{{$1}}</mark>')
  return <div className="token-textarea"><pre ref={preRef} aria-hidden="true"><code dangerouslySetInnerHTML={{ __html: `${highlighted}\n` }}/></pre><textarea aria-label={ariaLabel} value={value} disabled={disabled} placeholder={placeholder} spellCheck={false} onChange={onChange} onScroll={e => { if (preRef.current) preRef.current.scrollTop = (e.target as HTMLTextAreaElement).scrollTop }}/></div>
}
function CountUp({ value }: { value: number }) {
  const [display, setDisplay] = useState(0)
  const prevRef = useRef(0)
  useEffect(() => {
    const from = prevRef.current
    const to = Number(value) || 0
    if (from === to || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) { prevRef.current = to; setDisplay(to); return }
    const start = performance.now(); const dur = 550
    let raf = 0
    const step = (now: number) => { const p = Math.min(1, (now - start) / dur); const eased = 1 - Math.pow(1 - p, 3); setDisplay(Math.round(from + (to - from) * eased)); if (p < 1) raf = requestAnimationFrame(step); else prevRef.current = to }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [value])
  return <>{display}</>
}
function Ticker({ since }: { since: Date }) {
  const [, force] = useState(0)
  useEffect(() => { const timer = setInterval(() => force(x => x + 1), 1000); return () => clearInterval(timer) }, [])
  const secs = Math.max(0, Math.round((Date.now() - since.getTime()) / 1000))
  return <span className="ticker">{secs < 5 ? 'updated just now' : secs < 60 ? `updated ${secs}s ago` : `updated ${Math.round(secs / 60)}m ago`}</span>
}
function Donut({ segments, centerValue, centerLabel }: { segments: { label: string; value: number; color: string }[]; centerValue: number; centerLabel: string }) {
  const total = segments.reduce((sum, s) => sum + s.value, 0)
  let acc = 0
  const stops = segments.filter(s => s.value > 0).map(s => { const start = (acc / (total || 1)) * 360; acc += s.value; const end = (acc / (total || 1)) * 360; return `${s.color} ${start}deg ${end}deg` }).join(', ')
  return <div className="donut-layout"><div className="donut" style={{ background: total ? `conic-gradient(${stops})` : '#1b2a3a' }}><div><strong><CountUp value={centerValue}/></strong><span>{centerLabel}</span></div></div><div className="donut-legend">{segments.map(s => <div key={s.label}><i style={{ background: s.color }}/><span>{s.label}<b>{s.value}</b></span></div>)}</div></div>
}
function Select({ value, onChange, options, ariaLabel, name, className = '' }: { value: string; onChange: (e: { target: { name?: string; value: string } }) => void; options: (string | { value: string; label: string })[]; ariaLabel?: string; name?: string; className?: string }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => { const onDoc = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false) }; const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setOpen(false) }; document.addEventListener('mousedown', onDoc); document.addEventListener('keydown', onKey); return () => { document.removeEventListener('mousedown', onDoc); document.removeEventListener('keydown', onKey) } }, [])
  const opts = options.map(o => typeof o === 'string' ? { value: o, label: o } : o)
  const current = opts.find(o => o.value === value) || opts[0]
  return <div className={`select ${className} ${open ? 'open' : ''}`} ref={ref}><select className="native-select" aria-label={ariaLabel} name={name} value={value} onChange={e => onChange({ target: { name, value: e.target.value } })}>{opts.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}</select><button type="button" aria-haspopup="listbox" aria-expanded={open} aria-label={`${ariaLabel || name || 'Select'} menu`} onClick={() => setOpen(o => !o)}><span>{current?.label ?? value}</span><span className="chevron" aria-hidden="true">⌄</span></button>{open && <ul role="listbox">{opts.map(o => <li key={o.value} role="option" aria-selected={o.value === value} onClick={() => { onChange({ target: { name, value: o.value } }); setOpen(false) }}>{o.label}</li>)}</ul>}</div>
}

