  const submitRepo = async input => { try { const created = apiEnabled ? await createRepository(input, token || '', fetch) : { ...input, id: input.name, name: input.name, status: 'Ready', cacheState: 'Pending', activeFindingCount: 0 }; setRepos(current => [...current, created]); setModal(''); showNotice('Repository added') } catch (e) { showNotice('Repository could not be added') } }
  const submitDiscovery = async input => { try { const pattern = new RegExp(`^${input.pattern.trim().replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')}$`, 'i'); let candidates = input.organization.toLowerCase() === 'octocat' ? fallbackRepos : []; if (!apiEnabled && input.provider === 'github') { try { const response = await fetch(`https://api.github.com/orgs/${encodeURIComponent(input.organization.trim())}/repos?per_page=100`); if (response.ok) { const items = await response.json(); candidates = items.map(item => ({ id: item.full_name, name: item.full_name, cloneUrl: item.clone_url, provider: 'github', defaultBranch: item.default_branch || 'main', status: 'Ready', cacheState: 'Pending', activeFindingCount: 0 })) } } catch {} } const matches = candidates.filter(repo => pattern.test(repo.name.split('/').pop() || repo.name)); localStorage.setItem('aegis-discovery-rules', JSON.stringify([{ ...input, updatedAt: new Date().toISOString() }])); if (!matches.length) { showNotice('No repositories matched that discovery pattern'); return } setRepos(current => [...current, ...matches.filter(repo => !current.some(item => item.id === repo.id))]); setModal(''); showNotice(`Discovered ${matches.length} repository${matches.length === 1 ? '' : 'ies'}`) } catch { showNotice('Discovery could not be completed') } }
  const removeRepo = async repository => { if (!window.confirm(`Remove ${repository.name}?`)) return; try { if (apiEnabled) await deleteRepository(repository.id, token || '', fetch); setRepos(current => current.filter(item => item.id !== repository.id)); showNotice('Repository removed') } catch { showNotice('Repository could not be removed') } }
